DECLARE @ID_4816980f8b56 UNIQUEIDENTIFIER,
@Name_4816980f8b56 NVARCHAR(255),
@CategoryID_4816980f8b56 UNIQUEIDENTIFIER,
@UserQuestion_4816980f8b56 NVARCHAR(MAX),
@Description_4816980f8b56 NVARCHAR(MAX),
@SQL_4816980f8b56 NVARCHAR(MAX),
@TechnicalDescription_4816980f8b56 NVARCHAR(MAX),
@OriginalSQL_4816980f8b56 NVARCHAR(MAX),
@Feedback_4816980f8b56 NVARCHAR(MAX),
@Status_4816980f8b56 NVARCHAR(15),
@QualityRank_4816980f8b56 INT,
@ExecutionCostRank_4816980f8b56 INT,
@UsesTemplate_4816980f8b56 BIT,
@AuditQueryRuns_4816980f8b56 BIT,
@CacheEnabled_4816980f8b56 BIT,
@CacheTTLMinutes_4816980f8b56 INT,
@CacheMaxSize_4816980f8b56 INT,
@EmbeddingVector_4816980f8b56 NVARCHAR(MAX),
@EmbeddingModelID_4816980f8b56 UNIQUEIDENTIFIER,
@CacheValidationSQL_4816980f8b56 NVARCHAR(MAX),
@SQLDialectID_4816980f8b56 UNIQUEIDENTIFIER,
@Reusable_4816980f8b56 BIT,
@ExternalDataSourceID_4816980f8b56 UNIQUEIDENTIFIER,
@IsMaterialized_4816980f8b56 BIT
SET
  @ID_4816980f8b56 = '6C0A1000-0001-4000-A000-00000000000F'
SET
  @Name_4816980f8b56 = N'Common: Activity With Contact History'
SET
  @CategoryID_4816980f8b56 = '6C0A1000-0000-4000-A000-000000000001'
SET
  @UserQuestion_4816980f8b56 = N'What is the context and prior activity history for a specific activity?'
SET
  @Description_4816980f8b56 = N'Retrieves the target activity and the linked contact''s prior activities for relative sentiment and tagging analysis.'
SET
  @SQL_4816980f8b56 = N'-- Context query for Activity Sentiment & Tagging feature pipeline.
-- Returns the target activity along with the linked contact''s prior activities for baseline comparison.
SELECT
    targetActivity.ID AS TargetActivityID,
    targetActivity.Title AS TargetTitle,
    targetActivity.Description AS TargetDescription,
    targetActivity.StartedAt AS TargetStartedAt,
    targetActivity.Direction AS TargetDirection,
    targetActivity.Status AS TargetStatus,
    targetActivity.Outcome AS TargetOutcome,
    targetActivity.Details AS TargetDetails,
    linkedPerson.ID AS LinkedPersonID,
    linkedPerson.DisplayName AS LinkedPersonName,
    priorActivities.ID AS PriorActivityID,
    priorActivities.Title AS PriorTitle,
    priorActivities.Description AS PriorDescription,
    priorActivities.StartedAt AS PriorStartedAt,
    priorActivities.Direction AS PriorDirection,
    priorActivities.Outcome AS PriorOutcome,
    priorActivities.SentimentScore AS PriorSentimentScore
FROM [__mj_BizAppsCommon].[vwActivities] AS targetActivity
OUTER APPLY (
    SELECT TOP 1
        al.RecordID AS PersonID
    FROM [__mj_BizAppsCommon].[vwActivityLinks] al
    WHERE al.ActivityID = targetActivity.ID
      AND al.Entity = ''MJ_BizApps_Common: People''
) AS targetPersonLink
LEFT JOIN [__mj_BizAppsCommon].[vwPeople] AS linkedPerson
    ON linkedPerson.ID = targetPersonLink.PersonID
OUTER APPLY (
    SELECT TOP 10
        a.ID,
        a.Title,
        a.Description,
        a.StartedAt,
        a.Direction,
        a.Outcome,
        a.SentimentScore
    FROM [__mj_BizAppsCommon].[vwActivities] a
    INNER JOIN [__mj_BizAppsCommon].[vwActivityLinks] al2
        ON al2.ActivityID = a.ID
       AND al2.Entity = ''MJ_BizApps_Common: People''
       AND al2.RecordID = targetPersonLink.PersonID
    WHERE a.ID <> targetActivity.ID
      AND a.StartedAt <= targetActivity.StartedAt
    ORDER BY a.StartedAt DESC
) AS priorActivities
WHERE targetActivity.ID = {{ ActivityID | sqlString }};
'
SET
  @TechnicalDescription_4816980f8b56 = N'Joins vwActivities to vwActivityLinks for linked People records, pulling the last 10 prior activities for baseline context. Parameters: ActivityID.'
SET
  @Status_4816980f8b56 = N'Approved'
SET
  @QualityRank_4816980f8b56 = 9
SET
  @ExecutionCostRank_4816980f8b56 = 2
SET
  @UsesTemplate_4816980f8b56 = 1
SET
  @AuditQueryRuns_4816980f8b56 = 0
SET
